<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { profileApi } from '../api/profile'
import { tradingApi } from '../api/trading'
const loading=ref(true);const summary=ref<any>(null);const recommendations=ref<any>(null);const account=ref<any>(null);const error=ref('')
onMounted(async()=>{try{summary.value=(await profileApi.summary()).data.data; recommendations.value=(await profileApi.recommendations()).data.data;account.value=(await tradingApi.account()).data.data}catch(e:any){error.value=e.message}finally{loading.value=false}})
</script>
<template><section><div class="section-heading"><div><span class="eyebrow">CUSTOMER CONSOLE</span><h2>我的财富概览</h2><p>查看你的画像、资产快照和持仓数据。</p></div><span class="pill">客户前台</span></div><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="empty">正在读取你的资料…</div><template v-else><div class="metric-grid"><div class="metric-card"><span>账户可用余额</span><strong>¥{{account?.available_balance??0}}</strong></div><div class="metric-card"><span>总资产</span><strong>¥{{summary?.latest_asset?.total_asset??0}}</strong></div><div class="metric-card"><span>可投资资产</span><strong>¥{{summary?.latest_asset?.investable_asset??0}}</strong></div><div class="metric-card"><span>持仓数量</span><strong>{{summary?.holdings?.length??0}}</strong></div></div><div class="profile-panel"><span class="eyebrow">PROFILE</span><h3>{{summary?.profile?.investment_goal||'尚未填写投资目标'}}</h3><p>投资期限：{{summary?.profile?.investment_horizon||'未设置'}} · 流动性偏好：{{summary?.profile?.liquidity_preference||'未设置'}}</p></div><div class="section-heading compact"><h3>我的持仓</h3><span class="pill">构造数据</span></div><div v-if="!summary?.holdings?.length" class="empty">暂无持仓数据</div><article v-for="holding in summary.holdings" :key="holding.id" class="result"><div class="result-meta"><span>产品 {{holding.product_id}}</span><span>持有 {{holding.holding_days}} 天</span></div><p>市值：¥{{holding.market_value}} · 盈亏：¥{{holding.profit_loss}}</p></article><div class="section-heading compact"><h3>产品匹配</h3><span class="pill">确定性规则</span></div><div class="recommend-grid"><article v-for="item in recommendations?.matches||[]" :key="item.product_id" class="recommend-card matched"><strong>✓ {{item.product_name}}</strong><p v-for="reason in item.reasons" :key="reason">{{reason}}</p></article><article v-for="item in recommendations?.excluded||[]" :key="item.product_id" class="recommend-card excluded"><strong>× {{item.product_name}}</strong><p v-for="reason in item.reasons" :key="reason">{{reason}}</p></article></div><div class="section-heading compact"><h3>快捷操作</h3></div><div class="action-row"><RouterLink class="button" to="/orders">查看我的订单与交易</RouterLink><RouterLink class="text-button" to="/products">浏览产品</RouterLink></div></template></section></template>
